import Foundation

/// Bundled, verified emergency numbers. Never generated by a model.
enum EmergencyNumbers {
  static let table: [String: [String: String]] = {
    guard let url = Bundle.main.url(forResource: "EmergencyNumbers", withExtension: "json"),
          let data = try? Data(contentsOf: url),
          let table = try? JSONDecoder().decode([String: [String: String]].self, from: data)
    else { return [:] }
    return table
  }()

  static func numbers(for countryCode: String?) -> [String: String]? {
    guard let code = countryCode?.uppercased() else { return nil }
    return table[code]
  }
}
